solution.javascript:
function ladderLength(beginWord, endWord, wordList) {
  const set = new Set(wordList);
  if (!set.has(endWord)) return 0;
  const q = [[beginWord, 1]];
  set.delete(beginWord);
  while (q.length) {
    const [word, len] = q.shift();
    if (word === endWord) return len;
    const arr = word.split('');
    for (let i = 0; i < arr.length; i++) {
      const orig = arr[i];
      for (let c = 97; c <= 122; c++) {
        arr[i] = String.fromCharCode(c);
        const next = arr.join('');
        if (set.has(next)) { set.delete(next); q.push([next, len + 1]); }
      }
      arr[i] = orig;
    }
  }
  return 0;
}

solution.cpp:
int ladderLength(string beginWord, string endWord, vector<string>& wordList) {
    unordered_set<string> set(wordList.begin(), wordList.end());
    if (!set.count(endWord)) return 0;
    queue<pair<string,int>> q; q.push({beginWord, 1});
    set.erase(beginWord);
    while (!q.empty()) {
        auto [word, len] = q.front(); q.pop();
        if (word == endWord) return len;
        for (int i = 0; i < word.size(); i++) {
            char orig = word[i];
            for (char c = 'a'; c <= 'z'; c++) {
                word[i] = c;
                if (set.count(word)) { set.erase(word); q.push({word, len+1}); }
            }
            word[i] = orig;
        }
    }
    return 0;
}
